<?php require_once 'includes/db.php';require_once 'includes/functions.php';$count=(int)$conn->query("SELECT COUNT(*) n FROM admins")->fetch_assoc()['n'];$errors=[];$done=false;if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$count=(int)$conn->query("SELECT COUNT(*) n FROM admins")->fetch_assoc()['n'];if($count)$errors[]='An admin already exists. Use the login page.';if(mb_strlen($name)<2)$errors[]='Enter your name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(strlen($pass)<10)$errors[]='Password must be at least 10 characters.';if(!$errors){$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO admins(name,email,password_hash) VALUES(?,?,?)");$s->bind_param('sss',$name,$email,$hash);$s->execute();$done=true;}}$title='Admin setup';include 'includes/header.php';?><section class="login"><div class="form"><small>ONE-TIME SETUP</small><h1>Create admin account</h1><?php if($done):?><div class="flash">Admin created. <a href="admin/login.php">Sign in</a>. Delete setup_admin.php after setup.</div><?php elseif($count):?><p>An admin already exists. <a href="admin/login.php">Go to login</a>.</p><?php else:?><p>Choose your own email and password.</p><?php foreach($errors as $err):?><div class="flash"><?=e($err)?></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (10+ characters)<input type="password" name="password" minlength="10" required></label><button class="btn dark full">Create admin</button></form><?php endif;?></div></section><?php include 'includes/footer.php';?>